import { test, expect } from '@playwright/test';

test.describe('Customer Login to Sauce Demo Store', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should successfully log in with valid credentials and redirect to product catalogue', async ({ page }) => {
    // Locate and fill in the username field
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('standard_user');

    // Locate and fill in the password field
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('secret_sauce');

    // Locate and click the login button
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Wait for the redirect to complete
    await page.waitForURL('*://www.saucedemo.com/inventory.html');

    // Verify the page title contains 'Products'
    const pageTitle = page.getByText('Products');
    await expect(pageTitle).toBeVisible();

    // Verify the page title text
    await expect(pageTitle).toContainText('Products');

    // Verify the URL contains '/inventory.html'
    const currentURL = page.url();
    expect(currentURL).toContain('/inventory.html');
  });

  test('should display error message when logging in with invalid credentials', async ({ page }) => {
    // Locate and fill in the username field
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('invalid_user');

    // Locate and fill in the password field
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('wrong_password');

    // Locate and click the login button
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/invalid credentials/i);
    await expect(errorMessage).toBeVisible();

    // Verify the error message is displayed
    await expect(errorMessage).toBeVisible();

    // Verify the page title is still 'Products'
    const pageTitle = page.getByText('Products');
    await expect(pageTitle).toBeVisible();

    // Verify the URL remains the same
    const currentURL = page.url();
    expect(currentURL).toContain('/inventory.html');
  });
});
